import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"框架定位","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/positioning.md","filePath":"appendix/positioning.md","lastUpdated":1794364178000}`),a={name:`appendix/positioning.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="框架定位" tabindex="-1">框架定位 <a class="header-anchor" href="#框架定位" aria-label="Permalink to “框架定位”">​</a></h1><p>这一页回答一个问题：XiHan Framework 到底是什么，适合谁，又明确不做什么。读完它，你能判断自己的项目该不该用这个框架；要看它与同类框架的差别，再读<a href="/appendix/why">为什么是曦寒</a>。</p><h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to “一句话定位”">​</a></h2><p>XiHan Framework 是一套语言中立的应用框架规范（XiHan Spec）及其 .NET 参考实现，以「微内核、能力图谱、管道执行」为核心范式，通过能力包、插件、协议三条扩展轴组合能力，适用于 B2B SaaS、企业中后台、微服务与边缘服务。</p><p>这句话里的每个词都对应一组具体的工程约束，后面的章节逐一展开。这里先把三个关键词讲清楚：</p><table tabindex="0"><thead><tr><th>关键词</th><th>含义</th></tr></thead><tbody><tr><td>微内核</td><td>内核只定义宿主、能力图谱、执行管道、诊断、安全原语、操作契约与插件抽象，不含任何子系统实现；内核公开类型有预算上限，第三方依赖为零</td></tr><tr><td>能力图谱</td><td>每个特性在清单里按能力 ID 声明「我提供什么、我依赖什么」，内核在启动前求解整张图，缺失、循环、版本冲突与多候选都在启动期报错</td></tr><tr><td>管道执行</td><td>每次调用都经过固定十一个阶段的管道，认证、租户、授权、校验、幂等、事务是各阶段里的中间件，顺序确定、可打印、可测试</td></tr></tbody></table><h2 id="三层定位" tabindex="-1">三层定位 <a class="header-anchor" href="#三层定位" aria-label="Permalink to “三层定位”">​</a></h2><p>框架在三个层面各有一个定位，对标的参照物也不同：</p><table tabindex="0"><thead><tr><th>层</th><th>定位</th><th>对标参照</th></tr></thead><tbody><tr><td>原语与内核</td><td>十年不变的原语层，加大版本内稳定的微内核</td><td>Linux 系统调用 ABI、Rust 的 <code>core</code>、XNU 微内核</td></tr><tr><td>子系统能力</td><td>通用企业能力标准化：持久化、缓存、消息、安全、多租户、调度、工作流等，每个都是「抽象 + 默认实现 + Provider」</td><td>Dapr Building Blocks、Android Treble</td></tr><tr><td>协议与工具链</td><td>一份操作契约多协议暴露（HTTP、gRPC、MCP、命令行），打包与编排，分析器与生成器</td><td>FastAPI、ASGI、OCI、Service Binding</td></tr></tbody></table><p>原语层只增不改；内核在大版本内不破坏；子系统之上各自演进，通过同一套一致性测试即视为兼容。这就是我在<a href="/appendix/philosophy">设计哲学</a>里讲的「三易」。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>特征</th><th>框架给什么</th></tr></thead><tbody><tr><td>多租户 SaaS 平台</td><td>租户隔离、数据分片、订阅计划</td><td>Tenant 阶段解析租户，持久化层自动过滤，按租户分片选连接</td></tr><tr><td>企业后台管理系统</td><td>复杂权限、审批流、组织架构</td><td>RBAC 授予、条件引擎、工作流引擎、审计</td></tr><tr><td>行业垂直应用</td><td>CRM、ERP、WMS、HRM 等定制</td><td>能力包组织业务模块，默认实现让开发期不依赖外部设施</td></tr><tr><td>微服务后端</td><td>每个服务只装所需能力</td><td>Minimal 组合起步，远程能力经协议接入</td></tr><tr><td>开放 API 与 AI 工具平台</td><td>同一业务同时暴露为 REST、gRPC、MCP tool</td><td>操作契约一次声明，协议适配器各自翻译</td></tr><tr><td>边缘与轻量服务</td><td>冷启动敏感、资源受限</td><td>Minimal 组合 + Native AOT 发布</td></tr><tr><td>插件化平台</td><td>第三方扩展、任意语言、崩溃不拖垮宿主</td><td>进程内、Wasm、进程外三级隔离的插件宿主</td></tr></tbody></table><h2 id="不是什么" tabindex="-1">不是什么 <a class="header-anchor" href="#不是什么" aria-label="Permalink to “不是什么”">​</a></h2><p>明确说「不是」比说「是」更能帮你选型：</p><table tabindex="0"><thead><tr><th>不是</th><th>原因</th></tr></thead><tbody><tr><td>不是 ABP 的替代品或分支</td><td>架构哲学不同：特性组合与管道阶段，而不是强制模块基类与生命周期钩子</td></tr><tr><td>不是 Spring Boot 的 .NET 移植</td><td>.NET 有自己的最佳实践：Generic Host、源生成器、Native AOT</td></tr><tr><td>不是微服务框架</td><td>不绑定部署形态，单体、模块化单体、微服务都可以</td></tr><tr><td>不是 Sidecar 平台</td><td>能力在进程内组合，远程能力只是可选的 Provider</td></tr><tr><td>不是低代码平台</td><td>面向开发者，不面向拖拽配置</td></tr><tr><td>不是 ORM</td><td>持久化走端口与 Provider，EF Core 与 SqlSugar 各有适配包</td></tr><tr><td>不是 UI 组件库</td><td>前后端分离，前端由 XiHan.UI 独立演进</td></tr></tbody></table><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to “是什么”">​</a></h2><table tabindex="0"><thead><tr><th>是</th><th>具体含义</th></tr></thead><tbody><tr><td>规范与参考实现</td><td>XiHan Spec 定义原语、清单、上下文、管道、插件协议与协议映射；.NET 是参考实现，其他语言按规范实现并通过同一套一致性向量</td></tr><tr><td>开发效率基础设施</td><td>企业级通用能力开箱即用，每个抽象都有零外部依赖的默认实现</td></tr><tr><td>架构共识载体</td><td>统一的环层、依赖方向、术语表、命名文法与代码规范，由架构测试与分析器执行</td></tr><tr><td>能力集成平台</td><td>能力图谱协调多技术栈，而不是基类继承绑定</td></tr><tr><td>质量保障体系</td><td>内置可观测性、审计、错误模型、API 稳定性分级与一致性测试</td></tr><tr><td>可扩展宿主</td><td>微内核 + 能力包 + 插件 + 协议，按需组合，渐进增长</td></tr></tbody></table><h2 id="版本与兼容" tabindex="-1">版本与兼容 <a class="header-anchor" href="#版本与兼容" aria-label="Permalink to “版本与兼容”">​</a></h2><ul><li>全部包共享一条版本线，大版本每三年一次并对齐一个 .NET LTS，小版本约每六个月，补丁随时。</li><li>公开类型都带稳定性标记：<code>Stable</code>、<code>Preview</code>、<code>Experimental</code>、<code>Internal</code>、<code>Deprecated</code>。<code>Stable</code> 大版本内不破坏；<code>Preview</code> 与 <code>Experimental</code> 可能在小版本变更，每次变更都在更新日志给出迁移方式。原语层在 <code>Stable</code> 之上再加「冻结」承诺。</li><li>破坏性变更走三阶段弃用：先标 <code>Deprecated</code> 并给出迁移说明，至少保留两个小版本；下一个大版本前升级为编译错误；大版本移除并提供代码修复。</li><li>当前是预览版，公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整。</li></ul><h2 id="与-basicapp-的关系" tabindex="-1">与 BasicApp 的关系 <a class="header-anchor" href="#与-basicapp-的关系" aria-label="Permalink to “与 BasicApp 的关系”">​</a></h2><p><a href="https://github.com/XiHanFun/XiHan.BasicApp" target="_blank" rel="noreferrer">XiHan.BasicApp</a> 是基于本框架的参考应用，覆盖 SaaS 管理、组织架构、权限管理等业务场景，用能力包与操作契约实现。框架正式版的门槛之一，就是 BasicApp 全量跑在框架上。它同时是新项目的起点模板。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/appendix/why">为什么是曦寒</a>：与 ABP、Furion、MASA 的对比，以及换来的代价</li><li><a href="/appendix/philosophy">设计哲学</a>：三易模型、七条原则与借鉴矩阵</li><li><a href="/getting-started/concepts">核心概念</a>：开始学习框架本身</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};